import {useEffect,useState} from'react';
import {Check,ChevronRight,ClipboardList,Edit3,Loader2,MessageSquare,RefreshCw,X}from'lucide-react';
import {createSessionNote,decideSessionSuggestion,generateSessionSuggestions,getSessionBriefing,listSessionNotes,listSessionSuggestions}from'../../lib/practiceOperationsApi';

const groups=[['SINCE LAST SESSION','since_last_session'],['WHAT CHANGED','client_summary'],['OUTSTANDING','outstanding_actions'],['PROGRESS','recent_progress'],['ITEMS TO REVIEW','items_to_review']];
export function PreSessionBriefing({clientId,onStarted}){const[data,setData]=useState(null),[state,setState]=useState('loading'),[error,setError]=useState('');const load=async()=>{setState('loading');try{setData(await getSessionBriefing(clientId));setState('ready')}catch(reason){setError(reason.message||'Pre-session briefing could not load.');setState('error')}};useEffect(()=>{void load()},[clientId]);const start=async()=>{const note=await createSessionNote({client_id:clientId,note_type:'SESSION_NOTE',title:'Session note',sections:[]});onStarted?.(note.id)};if(state==='loading')return <div role="status" className="grid min-h-32 place-items-center"><Loader2 className="animate-spin"/><span className="sr-only">Loading pre-session briefing</span></div>;if(state==='error')return <div role="alert" className="rounded-xl bg-red-50 p-4 text-red-800">{error}<button onClick={load} className="ml-2 min-h-11"><RefreshCw className="inline"/> Retry</button></div>;return <section className="rounded-3xl border bg-white p-5"><header className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><p className="text-xs font-bold uppercase tracking-wider text-violet-700">Pre-session briefing</p><h3 className="mt-1 text-xl font-bold">Prepare with factual context</h3></div><button onClick={start} className="min-h-11 rounded-xl bg-violet-700 px-4 font-semibold text-white">Start Session <ChevronRight className="inline" size={17}/></button></header>{data.partial_data&&<p role="status" className="mt-4 rounded-xl bg-amber-50 p-3 text-sm text-amber-900">Partial data: no finalised prior session is available. Confirmed sources are shown below.</p>}<div className="mt-5 grid gap-3 md:grid-cols-2 xl:grid-cols-5">{groups.map(([label,key])=><article key={key} className="rounded-2xl bg-slate-50 p-4"><h4 className="text-[11px] font-bold tracking-wider text-slate-500">{label}</h4>{data[key]?.length?<ul className="mt-3 space-y-2">{data[key].slice(0,4).map((item,index)=><li key={`${item.source_ref}-${index}`} className="text-sm text-slate-700">{item.text}<small className="mt-1 block text-xs text-slate-400">Source: {item.source_ref}</small></li>)}</ul>:<p className="mt-3 text-sm text-slate-500">No confirmed items.</p>}</article>)}</div></section>}

export function PostSessionAssistant({clientId}){const[items,setItems]=useState([]),[state,setState]=useState('loading'),[error,setError]=useState('');const load=async()=>{setState('loading');try{const result=await listSessionSuggestions(clientId);setItems(result.items||[]);setState('ready')}catch(reason){setError(reason.message||'Post-session suggestions could not load.');setState('error')}};useEffect(()=>{void load()},[clientId]);const generate=async()=>{try{const notes=await listSessionNotes(clientId);const note=(notes.items||[]).find(item=>['FINALISED','AMENDED'].includes(item.status));if(!note){setError('Finalise a structured session before generating suggestions.');setState('error');return}await generateSessionSuggestions(note.id);await load()}catch(reason){setError(reason.message);setState('error')}};const decide=async(item,decision)=>{let proposed_payload;if(decision==='EDIT_AND_ACCEPT'){const title=window.prompt('Edit proposed title',item.proposed_payload?.title||'');if(title===null)return;proposed_payload={...item.proposed_payload,title}}await decideSessionSuggestion(item.id,{decision,proposed_payload});await load()};if(state==='loading')return <div role="status" className="grid min-h-28 place-items-center"><Loader2 className="animate-spin"/><span className="sr-only">Loading post-session suggestions</span></div>;if(state==='error')return <div role="alert" className="rounded-xl bg-red-50 p-4 text-red-800">{error}<button onClick={load} className="ml-2 min-h-11"><RefreshCw className="inline"/> Retry</button></div>;return <section className="rounded-3xl border bg-white p-5"><header className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><p className="text-xs font-bold uppercase tracking-wider text-emerald-700">Post-session assistant</p><h3 className="mt-1 text-xl font-bold">Practitioner-confirmed next actions</h3><p className="mt-1 text-sm text-slate-500">Suggestions never execute silently.</p></div><button onClick={generate} className="min-h-11 rounded-xl border px-4 font-semibold"><ClipboardList className="mr-1 inline" size={17}/>Prepare suggestions</button></header>{items.length?<div className="mt-5 space-y-3">{items.map(item=><article key={item.id} className="rounded-2xl bg-slate-50 p-4"><div className="flex gap-3"><MessageSquare className="text-emerald-700" size={18}/><div><strong>{item.suggestion_type.replaceAll('_',' ')}</strong><p className="mt-1 text-sm text-slate-600">{item.reason}</p><small className="text-xs text-slate-400">Source: {item.source.domain}:{item.source.id}</small></div></div>{item.status==='PROPOSED'?<div className="mt-4 flex flex-wrap gap-2"><button onClick={()=>decide(item,'ACCEPT')} className="min-h-11 rounded-xl bg-emerald-700 px-3 text-sm font-semibold text-white"><Check className="mr-1 inline" size={15}/>Accept</button><button onClick={()=>decide(item,'EDIT_AND_ACCEPT')} className="min-h-11 rounded-xl border px-3 text-sm font-semibold"><Edit3 className="mr-1 inline" size={15}/>Edit</button><button onClick={()=>decide(item,'DISMISS')} className="min-h-11 rounded-xl border px-3 text-sm font-semibold"><X className="mr-1 inline" size={15}/>Dismiss</button></div>:<p className="mt-3 text-xs font-bold text-slate-500">{item.status.replaceAll('_',' ')}</p>}</article>)}</div>:<p className="mt-5 rounded-2xl border border-dashed p-6 text-center text-sm text-slate-500">No post-session suggestions have been prepared.</p>}</section>}

export function SessionAssistant({clientId}){return <div className="space-y-5"><PreSessionBriefing clientId={clientId}/><PostSessionAssistant clientId={clientId}/></div>}
